    /**
     * Gets the item filter for a specific side of this machine.
     *
     * @param side Side
     * @param io   The IO mode this filter should be applicable to.
     * @return A {@code Predicate<ItemStack>} representing this filter
     */
    public Predicate<ItemStack> getItemCapFilter(@Nullable Direction side, IO io) {
        if (side != null) {
            var cover = getCoverContainer().getCoverAtSide(side);
            if (cover instanceof ItemFilterCover filterCover) {
                if (!filterCover.getFilterMode().filters(io)) {
                    if (filterCover.getAllowFlow() == ManualIOMode.DISABLED) {
                        return item -> false;
                    }
                    if (filterCover.getAllowFlow() == ManualIOMode.UNFILTERED) {
                        return item -> true;
                    }
                }
                return filterCover.getItemFilter();
            }
        }
        return item -> true;
    }

    /**
     * Gets the fluid filter for a specific side of this machine.
     *
     * @param side Side
     * @param io   The IO mode this filter should be applicable to.
     * @return A {@code Predicate<FluidStack>} representing this filter
     */
    public Predicate<FluidStack> getFluidCapFilter(@Nullable Direction side, IO io) {
        if (side != null) {
            var cover = getCoverContainer().getCoverAtSide(side);
            if (cover instanceof FluidFilterCover filterCover) {
                if (!filterCover.getFilterMode().filters(io)) {
                    if (filterCover.getAllowFlow() == ManualIOMode.DISABLED) {
                        return fluid -> false;
                    }
                    if (filterCover.getAllowFlow() == ManualIOMode.UNFILTERED) {
                        return fluid -> true;
                    }
                }
                return filterCover.getFluidFilter();
            }
        }
        return fluid -> true;
    }

    /**
     * Gets the item handler capability for a specific side of this machine
     *
     * @param side               The side
     * @param useCoverCapability Whether to return an item handler provided by an attached cover, if present.
     * @return The {@link IItemHandlerModifiable} capability, or null.
     */
    @Nullable
    public IItemHandlerModifiable getItemHandlerCap(@Nullable Direction side, boolean useCoverCapability) {
        var list = getAllTraits().stream()
                .filter(IItemHandlerModifiable.class::isInstance)
                .filter(t -> t.hasCapability(side))
                .map(IItemHandlerModifiable.class::cast)
                .toList();

        if (list.isEmpty()) return null;

        var io = IO.BOTH;
        var autoOutputTrait = getTrait(AutoOutputTrait.class);
        if (side != null && autoOutputTrait != null && autoOutputTrait.getItemOutputDirection() == side &&
                !autoOutputTrait.allowsItemInputFromOutputSide()) {
            io = IO.OUT;
        }

        IOFilteredInvWrapper handlerList = new IOFilteredInvWrapper(list, io,
                getItemCapFilter(side, IO.IN), getItemCapFilter(side, IO.OUT));
        if (!useCoverCapability || side == null) return handlerList;

        CoverBehavior cover = getCoverContainer().getCoverAtSide(side);
        return cover != null ? cover.getItemHandlerCap(handlerList) : handlerList;
    }

    /**
     * Gets the fluid handler capability for a specific side of this machine
     *
     * @param side               The side
     * @param useCoverCapability Whether to return a fluid handler provided by an attached cover, if present.
     * @return The {@link IFluidHandlerModifiable} capability, or null.
     */
    @Nullable
    public IFluidHandlerModifiable getFluidHandlerCap(@Nullable Direction side, boolean useCoverCapability) {
        var list = getAllTraits().stream()
                .filter(IFluidHandler.class::isInstance)
                .filter(t -> t.hasCapability(side))
                .map(IFluidHandler.class::cast)
                .toList();

        if (list.isEmpty()) return null;

        var io = IO.BOTH;
        var autoOutputTrait = getTrait(AutoOutputTrait.class);
        if (side != null && autoOutputTrait != null && autoOutputTrait.getFluidOutputDirection() == side &&
                !autoOutputTrait.allowsFluidInputFromOutputSide()) {
            io = IO.OUT;
        }

        IOFluidHandlerList handlerList = new IOFluidHandlerList(list, io, getFluidCapFilter(side, IO.IN),
                getFluidCapFilter(side, IO.OUT));
        if (!useCoverCapability || side == null) return handlerList;

        CoverBehavior cover = getCoverContainer().getCoverAtSide(side);
        return cover != null ? cover.getFluidHandlerCap(handlerList) : handlerList;
    }

    @Override
    public <T> LazyOptional<T> getCapability(Capability<T> cap, @Nullable Direction side) {
        var result = getCapability(this, cap, side);
        return result.isPresent() ? result : super.getCapability(cap, side);
    }

    private static <T> List<T> getCapabilitiesFromTraits(List<MachineTrait> traits, @Nullable Direction accessSide,
                                                         Class<T> capability) {
        if (traits.isEmpty()) return Collections.emptyList();
        List<T> list = new ArrayList<>();
        for (MachineTrait trait : traits) {
            if (trait.hasCapability(accessSide) && capability.isInstance(trait)) {
                list.add(capability.cast(trait));
            }
        }
        return list;
    }

    public static <T> LazyOptional<T> getCapability(MetaMachine machine, Capability<T> cap,
                                                    @Nullable Direction side) {
        if (cap == GTCapability.CAPABILITY_COVERABLE) {
            return GTCapability.CAPABILITY_COVERABLE.orEmpty(cap, LazyOptional.of(machine::getCoverContainer));
        } else if (cap == GTCapability.CAPABILITY_WORKABLE) {
            if (machine instanceof IWorkable workable) {
                return GTCapability.CAPABILITY_WORKABLE.orEmpty(cap, LazyOptional.of(() -> workable));
            }
            for (MachineTrait trait : machine.getAllTraits()) {
                if (trait instanceof IWorkable workable) {
                    return GTCapability.CAPABILITY_WORKABLE.orEmpty(cap, LazyOptional.of(() -> workable));
                }
            }
        } else if (cap == GTCapability.CAPABILITY_CONTROLLABLE) {
            if (machine instanceof IControllable controllable) {
                return GTCapability.CAPABILITY_CONTROLLABLE.orEmpty(cap, LazyOptional.of(() -> controllable));
            }
            for (MachineTrait trait : machine.getAllTraits()) {
                if (trait instanceof IControllable controllable) {
                    return GTCapability.CAPABILITY_CONTROLLABLE.orEmpty(cap, LazyOptional.of(() -> controllable));
                }
            }
        } else if (cap == GTCapability.CAPABILITY_ENERGY_CONTAINER) {
            if (machine instanceof IEnergyContainer energyContainer) {
                return GTCapability.CAPABILITY_ENERGY_CONTAINER.orEmpty(cap, LazyOptional.of(() -> energyContainer));
            }
            var list = getCapabilitiesFromTraits(machine.getAllTraits(), side, IEnergyContainer.class);
            if (!list.isEmpty()) {
                return GTCapability.CAPABILITY_ENERGY_CONTAINER.orEmpty(cap,
                        LazyOptional.of(() -> list.size() == 1 ? list.get(0) : new EnergyContainerList(list)));
            }
        } else if (cap == GTCapability.CAPABILITY_ENERGY_INFO_PROVIDER) {
            if (machine instanceof IEnergyInfoProvider energyInfoProvider) {
                return GTCapability.CAPABILITY_ENERGY_INFO_PROVIDER.orEmpty(cap,
                        LazyOptional.of(() -> energyInfoProvider));
            }
            var list = getCapabilitiesFromTraits(machine.getAllTraits(), side, IEnergyInfoProvider.class);
            if (!list.isEmpty()) {
                return GTCapability.CAPABILITY_ENERGY_INFO_PROVIDER.orEmpty(cap,
                        LazyOptional.of(() -> list.size() == 1 ? list.get(0) : new EnergyInfoProviderList(list)));
            }
        } else if (cap == ForgeCapabilities.ITEM_HANDLER) {
            var handler = machine.getItemHandlerCap(side, true);
            if (handler != null) {
                return ForgeCapabilities.ITEM_HANDLER.orEmpty(cap, LazyOptional.of(() -> handler));
            }
        } else if (cap == ForgeCapabilities.FLUID_HANDLER) {
            var handler = machine.getFluidHandlerCap(side, true);
            if (handler != null) {
                return ForgeCapabilities.FLUID_HANDLER.orEmpty(cap, LazyOptional.of(() -> handler));
            }
        } else if (cap == ForgeCapabilities.ENERGY) {
            if (machine instanceof IEnergyStorage energyStorage) {
                return ForgeCapabilities.ENERGY.orEmpty(cap, LazyOptional.of(() -> energyStorage));
            }
            var list = getCapabilitiesFromTraits(machine.getAllTraits(), side, IEnergyStorage.class);
            if (!list.isEmpty()) {
                // TODO wrap list in the future
                return ForgeCapabilities.ENERGY.orEmpty(cap, LazyOptional.of(() -> list.get(0)));
            }
        } else if (cap == GTCapability.CAPABILITY_LASER) {
            if (machine instanceof ILaserContainer energyContainer) {
                return GTCapability.CAPABILITY_LASER.orEmpty(cap, LazyOptional.of(() -> energyContainer));
            }
            var list = getCapabilitiesFromTraits(machine.getAllTraits(), side, ILaserContainer.class);
            if (!list.isEmpty()) {
                return GTCapability.CAPABILITY_LASER.orEmpty(cap,
                        LazyOptional.of(() -> list.size() == 1 ? list.get(0) : new LaserContainerList(list)));
            }
        } else if (cap == GTCapability.CAPABILITY_COMPUTATION_PROVIDER) {
            if (machine instanceof IOpticalComputationProvider computationProvider) {
                return GTCapability.CAPABILITY_COMPUTATION_PROVIDER.orEmpty(cap,
                        LazyOptional.of(() -> computationProvider));
            }
            var list = getCapabilitiesFromTraits(machine.getAllTraits(), side,
                    IOpticalComputationProvider.class);
            if (!list.isEmpty()) {
                return GTCapability.CAPABILITY_COMPUTATION_PROVIDER.orEmpty(cap, LazyOptional.of(() -> list.get(0)));
            }
        } else if (cap == GTCapability.CAPABILITY_DATA_ACCESS) {
            if (machine instanceof IDataAccessHatch computationProvider) {
                return GTCapability.CAPABILITY_DATA_ACCESS.orEmpty(cap, LazyOptional.of(() -> computationProvider));
            }
            var list = getCapabilitiesFromTraits(machine.getAllTraits(), side, IDataAccessHatch.class);
            if (!list.isEmpty()) {
                return GTCapability.CAPABILITY_DATA_ACCESS.orEmpty(cap, LazyOptional.of(() -> list.get(0)));
            }
        } else if (cap == GTCapability.CAPABILITY_MONITOR_COMPONENT) {
            if (machine instanceof IMonitorComponent monitorComponent) {
                return GTCapability.CAPABILITY_MONITOR_COMPONENT.orEmpty(cap, LazyOptional.of(() -> monitorComponent));
            }
            var list = getCapabilitiesFromTraits(machine.getAllTraits(), side, IMonitorComponent.class);
            if (!list.isEmpty()) {
                return GTCapability.CAPABILITY_MONITOR_COMPONENT.orEmpty(cap, LazyOptional.of(() -> list.get(0)));
            }
        }
        if (GTCEu.Mods.isAE2Loaded()) {
            LazyOptional<?> opt = AE2CallWrapper.getGridNodeHostCapability(cap, machine, side);
            if (opt.isPresent()) {
                // noinspection unchecked
                return (LazyOptional<T>) opt;
            }
        }
        return LazyOptional.empty();
    }

    public static class AE2CallWrapper {

        public static LazyOptional<?> getGridNodeHostCapability(Capability<?> cap, MetaMachine machine,
                                                                @Nullable Direction side) {
            if (cap == Capabilities.IN_WORLD_GRID_NODE_HOST) {
                if (machine instanceof IInWorldGridNodeHost nodeHost) {
                    return Capabilities.IN_WORLD_GRID_NODE_HOST.orEmpty(cap, LazyOptional.of(() -> nodeHost));
                }
                var list = getCapabilitiesFromTraits(machine.getAllTraits(), side,
                        IInWorldGridNodeHost.class);
                if (!list.isEmpty()) {
                    // TODO wrap list in the future (or not.)
                    return Capabilities.IN_WORLD_GRID_NODE_HOST.orEmpty(cap, LazyOptional.of(() -> list.get(0)));
                }
            }
            return LazyOptional.empty();
        }
    }

    // NBT keys for machine config values
    private static final String COVER = "cover";
    private static final String FACING_DIR = "front_facing";

    private static final String ITEM_OUTPUT_SIDE = "output_direction_item";
    private static final String ITEM_AUTO_OUTPUT = "item_auto_output";
    private static final String ALLOW_ITEM_IN_FROM_OUT = "allow_input_from_output_item";

    private static final String FLUID_OUTPUT_SIDE = "output_direction_fluid";
    private static final String FLUID_AUTO_OUTPUT = "fluid_auto_output";
    private static final String ALLOW_FLUID_IN_FROM_OUT = "allow_input_from_output_fluid";

    private static final String MUFFLED = "muffled";
    private static final String CIRCUIT = "circuit_config";

    @Override
    public void copyConfig(CompoundTag tag) {
        tag.putString(FACING_DIR, MachineConfigCopyBehaviour.directionToString(getFrontFacing()));

        var outputTrait = getTrait(AutoOutputTrait.class);
        if (outputTrait != null && outputTrait.supportsAutoOutputItems() &&
                outputTrait.getItemOutputDirection() != null) {
            tag.putString(ITEM_OUTPUT_SIDE,
                    MachineConfigCopyBehaviour.directionToString(outputTrait.getItemOutputDirection()));
            tag.putBoolean(ITEM_AUTO_OUTPUT, outputTrait.isAutoOutputItems());
            tag.putBoolean(ALLOW_ITEM_IN_FROM_OUT, outputTrait.allowsItemInputFromOutputSide());
        }

        if (outputTrait != null && outputTrait.supportsAutoOutputFluids() &&
                outputTrait.getFluidOutputDirection() != null) {
            tag.putString(FLUID_OUTPUT_SIDE,
                    MachineConfigCopyBehaviour.directionToString(outputTrait.getFluidOutputDirection()));
            tag.putBoolean(FLUID_AUTO_OUTPUT, outputTrait.isAutoOutputFluids());
            tag.putBoolean(ALLOW_FLUID_IN_FROM_OUT, outputTrait.allowsFluidInputFromOutputSide());
        }

        if (this instanceof IMufflableMachine mufflableMachine) {
            tag.putBoolean(MUFFLED, mufflableMachine.isMuffled());
        }

        var circuit = getTrait(ProgrammableCircuitSlotTrait.class);

        if (circuit != null && circuit.isEnabled() && circuit.getCurrentCircuit() != 0) {
            tag.putInt(CIRCUIT, circuit.getCurrentCircuit());
        }

        var coverTag = new CompoundTag();
        getCoverContainer().copyConfig(coverTag);
        tag.put(COVER, coverTag);
    }

    @Override
    public void pasteConfig(ServerPlayer player, CompoundTag tag) {
        var outputTrait = getTrait(AutoOutputTrait.class);
        if (outputTrait != null) {
            if (tag.contains(ITEM_OUTPUT_SIDE))
                outputTrait.setItemOutputDirection(
                        MachineConfigCopyBehaviour.stringToDirection(tag.getString(ITEM_OUTPUT_SIDE)));
            if (tag.contains(ITEM_AUTO_OUTPUT)) outputTrait.setAllowAutoOutputItems(tag.getBoolean(ITEM_AUTO_OUTPUT));
            if (tag.contains(ALLOW_ITEM_IN_FROM_OUT))
                outputTrait.setAllowItemInputFromOutputSide(tag.getBoolean(ALLOW_ITEM_IN_FROM_OUT));
            if (tag.contains(FLUID_OUTPUT_SIDE))
                outputTrait.setFluidOutputDirection(
                        MachineConfigCopyBehaviour.stringToDirection(tag.getString(FLUID_OUTPUT_SIDE)));
            if (tag.contains(FLUID_AUTO_OUTPUT))
                outputTrait.setAllowAutoOutputFluids(tag.getBoolean(FLUID_AUTO_OUTPUT));
            if (tag.contains(ALLOW_FLUID_IN_FROM_OUT))
                outputTrait.setAllowFluidInputFromOutputSide(tag.getBoolean(ALLOW_FLUID_IN_FROM_OUT));
        }

        Direction facingDir = Direction.byName(tag.getString(FACING_DIR));
        if (facingDir != null) setFrontFacing(facingDir);

        if (this instanceof IMufflableMachine mufflableMachine) {
            if (tag.contains(MUFFLED)) mufflableMachine.setMuffled(tag.getBoolean(MUFFLED));
        }

        if (tag.contains(CIRCUIT)) {
            getTraitOptional(ProgrammableCircuitSlotTrait.class)
                    .ifPresent(t -> t.setCurrentCircuit(tag.getInt(CIRCUIT)));
        }

        getCoverContainer().pasteConfig(player, tag.getCompound(COVER));
    }

    @Override
    public List<ItemStack> getItemsRequiredToPaste() {
        return coverContainer.getItemsRequiredToPaste();
    }
}

package com.gregtechceu.gtceu.api.sync_system;

import com.gregtechceu.gtceu.GTCEu;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformer;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformers;
import com.gregtechceu.gtceu.api.sync_system.managed.ISyncManaged;

import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;

import io.netty.buffer.Unpooled;
import it.unimi.dsi.fastutil.objects.ObjectOpenHashSet;
import it.unimi.dsi.fastutil.objects.ObjectSet;
import lombok.Setter;
import org.jetbrains.annotations.Nullable;

import java.lang.invoke.MethodHandle;
import java.lang.invoke.WrongMethodTypeException;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Class that holds all sync info for an {@link ISyncManaged} object.
 */
public class SyncDataHolder {

    private final ClassSyncData syncData;
    private final ISyncManaged holder;

    private final ObjectSet<String> dirtySyncFields = new ObjectOpenHashSet<>();
    @Setter
    private boolean hasDirtyChildSyncObject = false;
    private boolean resyncAll = false;

    public SyncDataHolder(ISyncManaged o) {
        holder = o;
        syncData = ClassSyncData.getClassData(o.getClass());
    }

    /**
     * Instructs the sync system that this field has been updated and must be synced with clients.
     * 
     * @param fieldName The field that has changed.
     */
    public void markClientSyncFieldDirty(String fieldName) {
        dirtySyncFields.add(fieldName);
        holder.markAsChanged();
    }

    public void resyncAllFields() {
        resyncAll = true;
        holder.markAsChanged();
    }

    public boolean needsSync() {
        return !dirtySyncFields.isEmpty() || resyncAll || hasDirtyChildSyncObject;
    }

    @SuppressWarnings("unchecked")
    public CompoundTag serializeNBT(HolderLookup.Provider lookup) {
        CompoundTag tag = new CompoundTag();
        for (var field : syncData.getServerSaveFields().values()) {
            Object currentValue = field.handle.get(holder);
            if (currentValue == null || !confirmTransformerPresent(field, holder)) continue;

            try {
                Tag nbtValue = ((ValueTransformer<Object>) Objects.requireNonNull(field.transformer))
                        .serializeNBT(currentValue,
                                new ValueTransformer.TransformerContext<>(holder, field.type, currentValue,
                                        field.fieldName,
                                        false, false, lookup));
                tag.put(field.nbtSaveKey, nbtValue);

            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to serialize field {}", field.fieldName, e);
            }
        }
        return tag;
    }

    @SuppressWarnings("unchecked")
    public void deserializeNBT(HolderLookup.Provider lookup, CompoundTag tag) {
        for (var field : syncData.getServerSaveFields().values()) {
            Tag newValue = tag.get(field.nbtSaveKey);
            if (newValue == null || newValue instanceof CompoundTag compound &&
                    (compound.isEmpty() || (compound.size() == 1 && compound.getBoolean("null"))))
                continue;

            if (!confirmTransformerPresent(field, holder)) continue;

            try {
                ValueTransformer<Object> transformer = (ValueTransformer<Object>) field.transformer;
                var current = field.handle.get(holder);

                Object result = Objects.requireNonNull(transformer).deserializeNBT(newValue,
                        new ValueTransformer.TransformerContext<>(
                                holder, field.type, current, field.fieldName, false, false, lookup));

                if (result != current) trySetField(field, holder, result);

            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to deserialize field {}", field.fieldName, e);
            }
        }
    }

    @SuppressWarnings("unchecked")
    public void writeClientPacket(HolderLookup.Provider lookup, FriendlyByteBuf buf) {
        Set<FieldSyncData> fieldsToSerialize = syncData.getClientSyncFields().values().stream()
                .filter(this::shouldSyncFieldToClient).collect(Collectors.toSet());

        var fieldData = new FriendlyByteBuf(Unpooled.buffer());
        boolean hadErrorWritingData = false;

        for (var field : fieldsToSerialize) {
            Object currentValue = field.handle.get(holder);

            fieldData.writeUtf(field.fieldName);
            fieldData.writeBoolean(currentValue == null);
            if (currentValue == null) continue;

            if (!confirmTransformerPresent(field, holder)) continue;

            try {
                ((ValueTransformer<Object>) Objects.requireNonNull(field.transformer))
                        .writeToPacket(fieldData, currentValue,
                                new ValueTransformer.TransformerContext<>(holder, field.type, currentValue,
                                        field.fieldName,
                                        true, resyncAll, lookup));
            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to write client packet on field {}", field.fieldName, e);
                hadErrorWritingData = true;
                break;
            }
        }

        resyncAll = false;
        dirtySyncFields.clear();
        hasDirtyChildSyncObject = false;

        if (hadErrorWritingData) {
            buf.writeVarInt(0);
            return;
        }

        buf.writeVarInt(fieldsToSerialize.size());
        buf.writeBytes(fieldData);
    }

    @SuppressWarnings("unchecked")
    public void readClientPacket(HolderLookup.Provider lookup, FriendlyByteBuf buf) {
        int fieldsToRead = buf.readVarInt();

        for (int fieldIndex = 0; fieldIndex < fieldsToRead; fieldIndex++) {
            String fieldName = buf.readUtf();
            FieldSyncData field = syncData.getClientSyncFields().get(fieldName);

            if (field == null) {
                GTCEu.LOGGER.error("Sync: Failed to read client packet: Unknown field {}", fieldName);
                return;
            }

            Object currentValue = field.handle.get(holder);

            boolean isNull = buf.readBoolean();
            if (isNull) {
                trySetField(field, holder, null);
                executeClientsideUpdateCallbacks(field);
                continue;
            }

            if (!confirmTransformerPresent(field, holder)) continue;

            try {
                Object result = ((ValueTransformer<Object>) Objects.requireNonNull(field.transformer))
                        .readFromPacket(buf,
                                new ValueTransformer.TransformerContext<>(holder, field.type, currentValue,
                                        field.fieldName,
                                        true, resyncAll, lookup));

                if (result != currentValue) {
                    trySetField(field, holder, result);
                }
                executeClientsideUpdateCallbacks(field);
            } catch (Exception e) {
                GTCEu.LOGGER.error("Sync: Failed to read client packet on field {}", field.fieldName, e);
                return;
            }

        }
    }

    private boolean shouldSyncFieldToClient(FieldSyncData field) {
        return (resyncAll || dirtySyncFields.contains(field.fieldName) ||
                field.handle.get(holder) instanceof ISyncManaged syncManaged &&
                        syncManaged.getSyncDataHolder().needsSync());
    }

    private void executeClientsideUpdateCallbacks(FieldSyncData field) {
        try {
            for (MethodHandle changeListenerHandle : field.changeListenerHandles) {
                changeListenerHandle.invoke(holder);
            }
        } catch (Throwable e) {
            if (e instanceof WrongMethodTypeException) {
                throw new IllegalArgumentException(
                        "Invalid method signature for change listener for field %s %s"
                                .formatted(field.fieldName, holder.getClass().getName()));
            }
            GTCEu.LOGGER.error("Sync: Error while invoking change listener for field {}", field.fieldName, e);
        }

        if (field.triggerClientRerender) holder.scheduleRenderUpdate();
    }

    @SuppressWarnings("BooleanMethodIsAlwaysInverted")
    private static boolean confirmTransformerPresent(FieldSyncData field, Object holder) {
        if (field.transformer == null) {
            field.setTransformer(ValueTransformers.get(field.type.getRawType()));
            if (field.transformer == null) {
                GTCEu.LOGGER.error(
                        "Sync: Failed to serialize/deserialize field {} in class {}: Missing value transformer for {}",
                        field.fieldName, holder.getClass().getName(), field.type);
                return false;
            }
        }
        return true;
    }

    private static void trySetField(FieldSyncData field, Object holder, @Nullable Object value) {
        try {
            field.handle.set(holder, value);
        } catch (Exception e) {
            if (e instanceof UnsupportedOperationException) {
                GTCEu.LOGGER.error(
                        "Sync: failed to perform VarHandle set: unsupported op on {} (you are probably trying to sync a final field)",
                        field.fieldName);
                return;
            }
            GTCEu.LOGGER.error("Sync: Failed to perform VarHandle set on {} : {}", field.fieldName, e);
        }
    }

    public static class SyncManagedTransformer implements ValueTransformer<ISyncManaged> {

        @Override
        public Tag serializeNBT(ISyncManaged value, TransformerContext<ISyncManaged> context) {
            return value.getSyncDataHolder().serializeNBT(context.lookup());
        }

        @Override
        public @Nullable ISyncManaged deserializeNBT(Tag tag, TransformerContext<ISyncManaged> context) {
            ISyncManaged syncManaged = context.currentValue();

            if (syncManaged == null) {
                GTCEu.LOGGER.error("Sync: ISyncManaged field was null, cannot instantiate {}",
                        context.fieldName());
                return null;
            }

            syncManaged.getSyncDataHolder().deserializeNBT(context.lookup(), (CompoundTag) tag);
            return syncManaged;
        }

        @Override
        public void writeToPacket(FriendlyByteBuf buf, ISyncManaged value, TransformerContext<ISyncManaged> context) {
            if (context.isClientFullSyncUpdate()) value.getSyncDataHolder().resyncAllFields();
            value.getSyncDataHolder().writeClientPacket(context.lookup(), buf);
        }

        @Override
        public @Nullable ISyncManaged readFromPacket(FriendlyByteBuf buf, TransformerContext<ISyncManaged> context) {
            ISyncManaged syncManaged = context.currentValue();
            var clazz = context.type().getClassValue();

            if (syncManaged == null && clazz != null && ISyncManaged.class.isAssignableFrom(clazz)) {
                var ctor = ClassSyncData.getClassData(clazz).getClientsideConstructor();
                if (ctor != null) syncManaged = (ISyncManaged) ctor.get();
            }

            if (syncManaged == null) {
                GTCEu.LOGGER.error("Sync: ISyncManaged field was null on client, cannot instantiate {}",
                        context.fieldName());
                return null;
            }

            syncManaged.getSyncDataHolder().readClientPacket(context.lookup(), buf);
            return syncManaged;
        }
    }
}

package com.gregtechceu.gtceu.api.sync_system.data_transformers;

import com.gregtechceu.gtceu.api.block.ICoilType;
import com.gregtechceu.gtceu.api.cover.CoverBehavior;
import com.gregtechceu.gtceu.api.data.chemical.material.Material;
